import os
os.environ.setdefault("MPLCONFIGDIR","/tmp/dysthe-mpl")
from pathlib import Path
import json,html,shutil
from PIL import Image,ImageDraw,ImageFont
from zipfile import ZipFile,ZIP_DEFLATED
root=Path(__file__).resolve().parent;out=root/'output/figure_review';items=json.loads((out/'catalog.json').read_text())
from matplotlib.font_manager import findfont
font=ImageFont.truetype(findfont('DejaVu Sans'),20)
for offset in range(0,len(items),4):
 canvas=Image.new('RGB',(1600,1040),'#e8eef2');draw=ImageDraw.Draw(canvas)
 for j,item in enumerate(items[offset:offset+4]):
  im=Image.open(out/item['png']);im.thumbnail((780,450));x=(j%2)*800;y=(j//2)*520
  canvas.paste(im,(x+(800-im.width)//2,y+35));draw.text((x+18,y+8),f"{item['number']:02d} / {item['title']}",font=font,fill='#18384b')
 canvas.save(out/f'contact_sheet_{offset//4+1}.png')
cards=[]
for item in items:
 n=item['number'];esc=html.escape
 cards.append(f'''<article data-category="{esc(item['category'])}" id="fig-{n}"><div class="meta"><span>FIGURE {n:02d} · {esc(item['category'])}</span><label><input type="checkbox" data-pick="{n}"> Shortlist</label></div><h2>{esc(item['title'])}</h2><button class="image" data-open="{n}" aria-label="Enlarge figure {n}"><img src="{esc(item['png'])}" alt="{esc(item['title'])}" loading="lazy"></button><p>{esc(item['caption'])}</p><div class="links"><a href="{esc(item['png'])}" target="_blank">Open full-resolution PNG ↗</a><a href="{esc(item['svg'])}" download>Download SVG</a></div><textarea data-note="{n}" placeholder="Your review notes for figure {n:02d}…" aria-label="Review notes for figure {n}"></textarea></article>''')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dysthe · figure review</title><style>
:root{--ink:#18384b;--teal:#168f9a}*{box-sizing:border-box}body{margin:0;background:#eef3f6;color:var(--ink);font:16px/1.6 system-ui,sans-serif}header{background:var(--ink);color:white;padding:45px max(24px,calc((100vw - 1320px)/2)) 35px}header small{color:#8ed5d9;letter-spacing:.16em}h1{font-size:clamp(30px,4vw,54px);font-weight:650;line-height:1.15;margin:15px 0}header p{max-width:900px;color:#d4e2ea}nav{display:flex;flex-wrap:wrap;gap:9px;align-items:center;position:sticky;top:0;z-index:2;background:#fff;padding:13px 24px;border-bottom:1px solid #d9e3e9}button,select{font:inherit;border:1px solid #c4d5df;border-radius:7px;background:white;color:var(--ink);padding:8px 13px;cursor:pointer}button.active,#export{background:var(--teal);color:white;border-color:var(--teal)}#count{margin-left:auto}main{max-width:1370px;margin:26px auto;padding:0 24px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}article{background:white;border-radius:14px;padding:24px;box-shadow:0 3px 14px #18384b09}article[hidden]{display:none}.meta{display:flex;justify-content:space-between;gap:10px;color:var(--teal);font-size:12px;font-weight:650;letter-spacing:.03em}.meta label{white-space:nowrap;cursor:pointer}h2{font-size:23px;line-height:1.25;margin:15px 0}.image{padding:0;border:none;display:block;width:100%;background:white;cursor:zoom-in}.image img{display:block;width:100%;height:auto}article p{font-size:14px;color:#486271}.links{display:flex;gap:18px;font-size:13px}a{color:#087a88}textarea{width:100%;min-height:70px;margin-top:18px;border:1px solid #d0dce3;border-radius:8px;padding:10px;font:14px system-ui;resize:vertical}footer{max-width:1320px;margin:35px auto;padding:20px;color:#486271}dialog{border:0;border-radius:12px;padding:15px;max-width:96vw;max-height:96vh}dialog::backdrop{background:#061b2cdb}dialog img{max-width:91vw;max-height:80vh;object-fit:contain;display:block}dialog .bar{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:10px}dialog p{max-width:1100px;font-size:14px}input{accent-color:var(--teal)}@media(max-width:850px){main{grid-template-columns:1fr}header{padding:30px 24px}nav{position:static}article{padding:17px}.meta{font-size:11px}}
</style></head><body><header><small>DYSTHE NUMERICAL STUDY · REVIEW EDITION · SEPTEMBER 10, 2026</small><h1>Waves, decay &amp; the figures worth keeping.</h1><p>20 standalone figures for evaluation before the next report. Start with the six wave-packet sequences, then compare the decay results and their numerical checks. Click any figure to inspect it, shortlist your favorites, and export your notes.</p><p><strong>Reading guide:</strong> amplitude is dimensionless. A 3D level surface shows three spatial coordinates; an oscillating slice adds an illustrative carrier. The later-time quadrature checks are pointwise evaluations, not new global-peak decay curves.</p></header><nav><button class="active" data-filter="All">All 20</button><button data-filter="Wave shapes">Wave shapes</button><button data-filter="Decay results">Decay results</button><button data-filter="Reliability">Reliability</button><button data-filter="Experiment design">Experiment design</button><button data-filter="Shortlisted">Shortlisted</button><span id="count"></span><button id="export">Export review notes</button></nav><main>'''+''.join(cards)+'''</main><footer>Figures use new qualitative snapshots and existing numerical results, as described in their captions. SVG files retain vector labels and curves; dense 3D surfaces are rasterized. Notes are saved in this browser when local storage is available. Export them to keep or share your selections.</footer><dialog id="viewer"><div class="bar"><strong id="viewTitle"></strong><div><button id="prev">← Previous</button> <button id="next">Next →</button> <button id="close">Close ✕</button></div></div><img id="viewImage" alt=""><p id="viewCaption"></p></dialog><script>
const items='''+json.dumps(items)+''';let saved={};try{saved=JSON.parse(localStorage.getItem('dysthe-figure-review-v1')||'{}')}catch(e){}let current=0,filter='All';const qs=s=>document.querySelector(s);function persist(){try{localStorage.setItem('dysthe-figure-review-v1',JSON.stringify(saved))}catch(e){}update()}function update(){let picked=0;for(const item of items){const s=saved[item.number]||{};if(s.pick)picked++;qs('#fig-'+item.number).hidden=filter==='Shortlisted'?!s.pick:filter!=='All'&&item.category!==filter}qs('#count').textContent=picked+' shortlisted'}document.querySelectorAll('[data-pick]').forEach(el=>{el.checked=!!saved[el.dataset.pick]?.pick;el.onchange=()=>{const n=el.dataset.pick;saved[n]={...saved[n],pick:el.checked};persist()}});document.querySelectorAll('[data-note]').forEach(el=>{el.value=saved[el.dataset.note]?.note||'';el.oninput=()=>{const n=el.dataset.note;saved[n]={...saved[n],note:el.value};persist()}});document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===el));update()});function show(n){current=(n+items.length)%items.length;const item=items[current];qs('#viewTitle').textContent=String(item.number).padStart(2,'0')+' / '+item.title;qs('#viewImage').src=item.png;qs('#viewImage').alt=item.title;qs('#viewCaption').textContent=item.caption;if(!qs('#viewer').open)qs('#viewer').showModal()}document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>show(Number(el.dataset.open)-1));qs('#prev').onclick=()=>show(current-1);qs('#next').onclick=()=>show(current+1);qs('#close').onclick=()=>qs('#viewer').close();document.addEventListener('keydown',e=>{if(qs('#viewer').open&&e.key==='ArrowLeft')show(current-1);if(qs('#viewer').open&&e.key==='ArrowRight')show(current+1)});qs('#export').onclick=()=>{let text='Dysthe figure review\\n\\n';for(const item of items){const s=saved[item.number]||{};if(s.pick||s.note)text+=`${s.pick?'[SHORTLISTED] ':''}${item.number}. ${item.title}\n${s.note||''}\n\n`}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download='dysthe_figure_review_notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};update();
</script></body></html>'''
(out/'index.html').write_text(page)
lines=['# Figure review collection','', 'Open index.html in a browser. Select Shortlist and enter notes; export the review to retain/share it.','', '20 figures, each as a 220-dpi PNG and an SVG. Dense 3D surfaces are rasterized within SVG; labels and regular curves remain vector. This is a figure collection, not a new report.','', 'New wave snapshots use the homogeneous canonical propagator at t=0,4,8, grid 192³, length 144, spacing 0.75, discrete L1 normalization. These visual samples are not a new convergence audit. Existing analytical results retain the qualifications in each caption.','']
for item in items:lines.extend([f"## {item['number']:02d}. {item['title']}",item['caption'],''])
(out/'README.md').write_text('\n'.join(lines))
shutil.copy2(root/'make_figure_review.py',out/'make_figure_review.py');shutil.copy2(root/'build_figure_gallery.py',out/'build_figure_gallery.py')
with ZipFile(root/'output/dysthe_figure_review.zip','w',ZIP_DEFLATED) as z:
 for f in sorted(out.iterdir()):
  if f.is_file():z.write(f,Path('figure_review')/f.name)
print('Review gallery and archive complete')
